    document.getElementById('ocm-plan-reset')?.addEventListener('click', () => { Object.assign(p, { ours: 0, theirs: 0, ourPace: 0, theirPace: 0, ourRph: 0, theirRph: 0, warlord: 17 }); warRenderPlanner(host); });
